content:
:root {
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-bg: #fee2e2;
  --color-danger-text: #b91c1c;
  --color-warning-bg: #fef3c7;
  --color-warning-text: #b45309;
  --color-success-bg: #dcfce7;
  --color-success-text: #15803d;
  --color-gray-50: #f9fafb;
  --color-gray-100: #f3f4f6;
  --color-gray-200: #e5e7eb;
  --color-gray-300: #d1d5db;
  --color-gray-400: #9ca3af;
  --color-gray-600: #4b5563;
  --color-gray-700: #374151;
  --color-gray-800: #1f2937;
  --color-gray-900: #111827;
  --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: #f1f5f9;
  color: var(--color-gray-800);
  line-height: 1.5;
  min-height: 100vh;
}

/* App Container */
.app-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* App Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--color-gray-200);
}

.header-title {
  font-size: 24px;
  font-weight: 700;
  color: var(--color-gray-900);
  margin-bottom: 4px;
}

.header-subtitle {
  font-size: 14px;
  color: var(--color-gray-600);
}

.header-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.search-input {
  padding: 8px 12px;
  border: 1px solid var(--color-gray-300);
  border-radius: var(--radius-md);
  font-size: 14px;
  min-width: 220px;
  background-color: #ffffff;
  color: var(--color-gray-800);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 500;
  font-size: 14px;
  padding: 8px 16px;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--color-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-secondary {
  background-color: var(--color-gray-100);
  color: var(--color-gray-700);
  border-color: var(--color-gray-300);
}

.btn-secondary:hover {
  background-color: var(--color-gray-200);
}

.btn-danger {
  background-color: var(--color-danger-bg);
  color: var(--color-danger-text);
  border-color: #fca5a5;
}

.btn-danger:hover {
  background-color: var(--color-danger);
  color: #ffffff;
}

.btn-sm {
  padding: 4px 8px;
  font-size: 12px;
  border-radius: var(--radius-sm);
}

/* Kanban Board Layout */
.kanban-board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: flex-start;
  flex: 1;
}

/* Kanban Column */
.kanban-column {
  background-color: #ffffff;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
  display: flex;
  flex-direction: column;
  min-height: 480px;
  box-shadow: var(--shadow-sm);
}

.column-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-gray-200);
  background-color: var(--color-gray-50);
  border-top-left-radius: var(--radius-lg);
  border-top-right-radius: var(--radius-lg);
}

.column-title-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.column-title-group h3 {
  font-size: 15px;
  font-weight: 600;
  color: var(--color-gray-800);
}

.column-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-gray-200);
  color: var(--color-gray-700);
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  margin-left: 4px;
}

.column-add-btn {
  background-color: transparent;
  color: var(--color-gray-600);
  border: 1px dashed var(--color-gray-300);
}

.column-add-btn:hover {
  background-color: var(--color-gray-100);
  color: var(--color-gray-800);
  border-color: var(--color-gray-400);
}

.column-body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 200px;
  transition: background-color 0.15s ease, border-color 0.15s ease;
  border-bottom-left-radius: var(--radius-lg);
  border-bottom-right-radius: var(--radius-lg);
}

.column-drop-active {
  background-color: #eff6ff;
  outline: 2px dashed var(--color-primary);
  outline-offset: -4px;
}

/* Task Card */
.task-card {
  background-color: #ffffff;
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-md);
  padding: 12px;
  box-shadow: var(--shadow-sm);
  cursor: grab;
  transition: box-shadow 0.15s ease, transform 0.15s ease, opacity 0.15s ease;
  user-select: none;
}

.task-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-gray-300);
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.4;
  border: 1px dashed var(--color-primary);
  background-color: #f8fafc;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.card-priority {
  font-size: 11px;
  font-weight: 600;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  display: inline-block;
}

.priority-high {
  background-color: var(--color-danger-bg);
  color: var(--color-danger-text);
}

.priority-medium {
  background-color: var(--color-warning-bg);
  color: var(--color-warning-text);
}

.priority-low {
  background-color: var(--color-success-bg);
  color: var(--color-success-text);
}

.card-actions {
  display: flex;
  gap: 4px;
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-gray-900);
  margin-bottom: 6px;
  word-break: break-word;
}

.card-desc {
  font-size: 12px;
  color: var(--color-gray-600);
  margin-bottom: 10px;
  line-height: 1.4;
  word-break: break-word;
  white-space: pre-wrap;
}

.card-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding-top: 8px;
  border-top: 1px solid var(--color-gray-100);
}

.card-move-btns {
  display: flex;
  gap: 4px;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(17, 24, 39, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 1000;
}

.modal-container {
  background-color: #ffffff;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 480px;
  max-height: 90vh;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 20px;
  border-bottom: 1px solid var(--color-gray-200);
}

.modal-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--color-gray-900);
}

.modal-close-btn {
  background: transparent;
  border: none;
  font-size: 22px;
  color: var(--color-gray-400);
  cursor: pointer;
  line-height: 1;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: color 0.15s ease;
}

.modal-close-btn:hover {
  color: var(--color-gray-700);
}

.modal-body {
  padding: 20px;
}

.form-group {
  margin-bottom: 16px;
}

.form-group:last-child {
  margin-bottom: 0;
}

.form-label {
  display: block;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-gray-700);
  margin-bottom: 6px;
}

.form-input,
.form-textarea,
.form-select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--color-gray-300);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-family: inherit;
  color: var(--color-gray-800);
  background-color: #ffffff;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.form-input:focus,
.form-textarea:focus,
.form-select:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.form-textarea {
  min-height: 90px;
  resize: vertical;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 16px 20px;
  border-top: 1px solid var(--color-gray-200);
  background-color: var(--color-gray-50);
  border-bottom-left-radius: var(--radius-lg);
  border-bottom-right-radius: var(--radius-lg);
}

/* Responsive */
@media (max-width: 860px) {
  .kanban-board {
    grid-template-columns: 1fr;
  }

  .app-header {
    flex-direction: column;
    align-items: stretch;
  }

  .header-controls {
    flex-direction: column;
    align-items: stretch;
  }

  .search-input {
    min-width: 100%;
  }

  .header-controls .btn-primary {
    width: 100%;
  }
}

import type { DragEvent } from 'react';

export type TaskStatus = 'todo' | 'in_progress' | 'done';

export type Priority = 'high' | 'medium' | 'low';

export type PriorityLabels = Record<Priority, string>;

export interface TaskItem {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: Priority;
  createdAt: string;
  updatedAt?: string;
}

export type TaskFormData = Omit<TaskItem, 'id' | 'createdAt' | 'updatedAt'>;

export interface ColumnDef {
  id: TaskStatus;
  title: string;
  color: string;
}

export interface TaskCardProps {
  task: TaskItem;
  onDragStart?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onEdit?: (task: TaskItem) => void;
  onDelete?: (id: string) => void;
  onMoveStatus?: (id: string, nextStatus: TaskStatus) => void;
}

export interface KanbanColumnProps {
  column: ColumnDef;
  tasks: TaskItem[];
  onDragOver?: (e: DragEvent<HTMLDivElement>) => void;
  onDrop?: (e: DragEvent<HTMLDivElement>, status: TaskStatus) => void;
  onDragStart?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onEdit?: (task: TaskItem) => void;
  onDelete?: (id: string) => void;
  onMoveStatus?: (id: string, nextStatus: TaskStatus) => void;
  onAddTaskClick?: (status: TaskStatus) => void;
}

export interface TaskModalProps {
  isOpen: boolean;
  taskToEdit: TaskItem | null;
  defaultStatus: TaskStatus;
  onClose?: () => void;
  onSave?: (taskData: TaskFormData, taskId?: string) => void;
}

import { useState, type DragEvent } from 'react';
import type { TaskCardProps, Priority } from '../types';

const PRIORITY_LABELS: Record<Priority, string> = {
  high: '高',
  medium: '中',
  low: '低',
};

const TaskCard = ({
  task,
  onDragStart,
  onEdit,
  onDelete,
  onMoveStatus,
}: TaskCardProps) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragStart = (e: DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    e.dataTransfer.setData('text/plain', task.id);
    onDragStart?.(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const priorityClass =
    task.priority === 'high'
      ? 'priority-high'
      : task.priority === 'medium'
      ? 'priority-medium'
      : 'priority-low';

  const cardClasses = isDragging
    ? 'task-card task-card-dragging'
    : 'task-card';

  const handlePrevMove = () => {
    if (task.status === 'in_progress') {
      onMoveStatus?.(task.id, 'todo');
    } else if (task.status === 'done') {
      onMoveStatus?.(task.id, 'in_progress');
    }
  };

  const handleNextMove = () => {
    if (task.status === 'todo') {
      onMoveStatus?.(task.id, 'in_progress');
    } else if (task.status === 'in_progress') {
      onMoveStatus?.(task.id, 'done');
    }
  };

  const formattedDate = (() => {
    if (!task.createdAt) return '';
    try {
      const d = new Date(task.createdAt);
      if (Number.isNaN(d.getTime())) return '';
      return `${d.getFullYear()}/${(d.getMonth() + 1).toString().padStart(2, '0')}/${d.getDate().toString().padStart(2, '0')}`;
    } catch {
      return '';
    }
  })();

  return (
    <div
      className={cardClasses}
      draggable
      tabIndex={0}
      role="article"
      aria-grabbed={isDragging}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="card-header">
        <span className={`card-priority ${priorityClass}`}>
          {PRIORITY_LABELS[task.priority] || task.priority}
        </span>
        <div className="card-actions">
          <button
            type="button"
            className="btn btn-sm btn-secondary"
            onClick={() => onEdit?.(task)}
            title="タスクを編集"
          >
            編集
          </button>
          <button
            type="button"
            className="btn btn-sm btn-danger"
            onClick={() => onDelete?.(task.id)}
            title="タスクを削除"
          >
            削除
          </button>
        </div>
      </div>

      <h4 className="card-title">{task.title}</h4>

      {task.description && (
        <p className="card-desc">{task.description}</p>
      )}

      <div className="card-footer">
        {formattedDate && (
          <span
            style={{
              fontSize: '11px',
              color: 'var(--color-text-muted, #6b7280)',
            }}
          >
            {formattedDate}
          </span>
        )}
        <div className="card-move-btns">
          {task.status !== 'todo' && (
            <button
              type="button"
              className="btn btn-sm btn-secondary"
              onClick={handlePrevMove}
              title="前のステータスへ移動"
            >
              ← 戻す
            </button>
          )}
          {task.status !== 'done' && (
            <button
              type="button"
              className="btn btn-sm btn-secondary"
              onClick={handleNextMove}
              title="次のステータスへ進める"
            >
              進める →
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default TaskCard;

import { useState, type DragEvent } from 'react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

const KanbanColumn = ({
  column,
  tasks = [],
  onDragOver,
  onDrop,
  onDragStart,
  onEdit,
  onDelete,
  onMoveStatus,
  onAddTaskClick,
}: KanbanColumnProps) => {
  const [isDragOver, setIsDragOver] = useState(false);

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setIsDragOver(true);
    onDragOver?.(e);
  };

  const handleDragLeave = () => {
    setIsDragOver(false);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragOver(false);
    onDrop?.(e, column.id);
  };

  const bodyClass = isDragOver
    ? 'column-body column-drop-active'
    : 'column-body';

  return (
    <div className="kanban-column">
      <div className="column-header">
        <div className="column-title-group">
          <span
            aria-hidden="true"
            style={{
              display: 'inline-block',
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: column.color || 'var(--color-primary)',
            }}
          />
          <h3>{column.title}</h3>
          <span className="column-badge">{tasks.length}</span>
        </div>
        <button
          type="button"
          className="btn btn-sm column-add-btn"
          onClick={() => onAddTaskClick?.(column.id)}
          title={`${column.title}にタスクを追加`}
        >
          + 追加
        </button>
      </div>

      <div
        className={bodyClass}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        {tasks.length === 0 ? (
          <div
            style={{
              flex: 1,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '24px 16px',
              color: 'var(--color-gray-400)',
              fontSize: '13px',
              border: '1px dashed var(--color-gray-300)',
              borderRadius: 'var(--radius-md)',
              backgroundColor: 'var(--color-gray-50)',
              userSelect: 'none',
            }}
          >
            タスクがありません
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onEdit={onEdit}
              onDelete={onDelete}
              onMoveStatus={onMoveStatus}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default KanbanColumn;

import { useState, useEffect, type FormEvent, type MouseEvent } from 'react';
import type { TaskModalProps, TaskStatus, Priority } from '../types';

const TITLE_MAX_LENGTH = 100;

const TaskModal = ({
  isOpen,
  taskToEdit,
  defaultStatus,
  onClose,
  onSave,
}: TaskModalProps) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<TaskStatus>(defaultStatus);
  const [priority, setPriority] = useState<Priority>('medium');
  const [error, setError] = useState('');

  useEffect(() => {
    if (taskToEdit) {
      setTitle(taskToEdit.title);
      setDescription(taskToEdit.description);
      setStatus(taskToEdit.status);
      setPriority(taskToEdit.priority);
    } else {
      setTitle('');
      setDescription('');
      setStatus(defaultStatus);
      setPriority('medium');
    }
    setError('');
  }, [taskToEdit, defaultStatus, isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose?.();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  const handleBackdropClick = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose?.();
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('タイトルを入力してください');
      return;
    }
    if (trimmedTitle.length > TITLE_MAX_LENGTH) {
      setError(`タイトルは${TITLE_MAX_LENGTH}文字以内で入力してください`);
      return;
    }

    onSave?.(
      {
        title: trimmedTitle,
        description: description.trim(),
        status,
        priority,
      },
      taskToEdit?.id
    );
    onClose?.();
  };

  return (
    <div className="modal-backdrop" onClick={handleBackdropClick}>
      <div
        className="modal-container"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        <div className="modal-header">
          <h3 id="modal-title" className="modal-title">
            {taskToEdit ? 'タスクの編集' : '新しいタスクを作成'}
          </h3>
          <button
            type="button"
            className="modal-close-btn"
            onClick={onClose}
            aria-label="閉じる"
          >
            ×
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {error && (
              <div style={{ color: 'var(--color-danger, #ef4444)', marginBottom: '12px', fontSize: '13px' }}>
                {error}
              </div>
            )}

            <div className="form-group">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <label className="form-label" htmlFor="task-title">
                  タイトル <span style={{ color: 'var(--color-danger, #ef4444)' }}>*</span>
                </label>
                <span style={{ fontSize: '12px', color: title.length >= TITLE_MAX_LENGTH ? 'var(--color-danger, #ef4444)' : 'var(--color-text-muted, #6b7280)' }}>
                  {title.length}/{TITLE_MAX_LENGTH}
                </span>
              </div>
              <input
                id="task-title"
                type="text"
                className="form-input"
                placeholder="タスク名を入力..."
                value={title}
                maxLength={TITLE_MAX_LENGTH}
                onChange={(e) => {
                  setTitle(e.target.value);
                  if (error) setError('');
                }}
                autoFocus
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-desc">
                説明
              </label>
              <textarea
                id="task-desc"
                className="form-textarea"
                placeholder="詳細な説明やメモを入力..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-status">
                ステータス
              </label>
              <select
                id="task-status"
                className="form-select"
                value={status}
                onChange={(e) => setStatus(e.target.value as TaskStatus)}
              >
                <option value="todo">未着手</option>
                <option value="in_progress">作業中</option>
                <option value="done">完了</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-priority">
                優先度
              </label>
              <select
                id="task-priority"
                className="form-select"
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
              >
                <option value="high">高</option>
                <option value="medium">中</option>
                <option value="low">低</option>
              </select>
            </div>
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button type="submit" className="btn btn-primary">
              {taskToEdit ? '更新する' : '作成する'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;

import { useState, useEffect, type DragEvent } from 'react';
import type { TaskItem, TaskStatus, ColumnDef } from './types';
import KanbanColumn from './components/KanbanColumn';
