  },
];

const generateTaskId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `task-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
};

const App = () => {
  const [tasks, setTasks] = useState<TaskItem[]>(() => {
    if (typeof window === 'undefined') return INITIAL_TASKS;
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return parsed;
        }
      }
    } catch {
      // ignore JSON parse error and fallback
    }
    return INITIAL_TASKS;
  });

  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [taskToEdit, setTaskToEdit] = useState<TaskItem | null>(null);
  const [defaultStatus, setDefaultStatus] = useState<TaskStatus>('todo');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch {
      // ignore storage error
    }
  }, [tasks]);

  const handleDragStart = (e: DragEvent<HTMLDivElement>, taskId: string) => {
    e.dataTransfer.setData('text/plain', taskId);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>, targetStatus: TaskStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    if (!taskId) return;

    setTasks((prev) =>
      prev.map((t) => (t.id === taskId ? { ...t, status: targetStatus } : t))
    );
  };

  const handleMoveStatus = (taskId: string, nextStatus: TaskStatus) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === taskId ? { ...t, status: nextStatus } : t))
    );
  };

  const handleOpenCreateModal = (status: TaskStatus = 'todo') => {
    setTaskToEdit(null);
    setDefaultStatus(status);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: TaskItem) => {
    setTaskToEdit(task);
    setDefaultStatus(task.status);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setTaskToEdit(null);
  };

  const handleSaveTask = (
    taskData: Omit<TaskItem, 'id' | 'createdAt'>,
    taskId?: string
  ) => {
    if (taskId) {
      setTasks((prev) =>
        prev.map((t) =>
          t.id === taskId ? { ...t, ...taskData } : t
        )
      );
    } else {
      const newTask: TaskItem = {
        ...taskData,
        id: generateTaskId(),
        createdAt: new Date().toISOString(),
      };
      setTasks((prev) => [newTask, ...prev]);
    }
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== taskId));
  };

  const filteredTasks = tasks.filter((task) => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      task.title.toLowerCase().includes(q) ||
      task.description.toLowerCase().includes(q)
    );
  });

  return (
    <div className="app-container">
      <header className="app-header">
        <div>
          <h1 className="header-title">カンバンボード</h1>
          <p className="header-subtitle">
            ドラッグ＆ドロップでタスクの進捗を直感的に管理できます
          </p>
        </div>

        <div className="header-controls">
          <input
            type="search"
            className="search-input"
            placeholder="タスクを検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => handleOpenCreateModal('todo')}
          >
            + タスクを追加
          </button>
        </div>
      </header>

      {filteredTasks.length === 0 && searchQuery.trim() !== '' ? (
        <div
          style={{
            padding: '48px 16px',
            textAlign: 'center',
            color: 'var(--color-gray-600)',
            backgroundColor: '#ffffff',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--color-gray-200)',
            boxShadow: 'var(--shadow-sm)',
          }}
        >
          一致するタスクが見つかりませんでした
        </div>
      ) : (
        <main className="kanban-board">
          {COLUMNS.map((column) => {
            const columnTasks = filteredTasks.filter(
              (t) => t.status === column.id
            );
            return (
              <KanbanColumn
                key={column.id}
                column={column}
                tasks={columnTasks}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                onDragStart={handleDragStart}
                onEdit={handleOpenEditModal}
                onDelete={handleDeleteTask}
                onMoveStatus={handleMoveStatus}
                onAddTaskClick={handleOpenCreateModal}
              />
            );
          })}
        </main>
      )}

      <TaskModal
        isOpen={isModalOpen}
        taskToEdit={taskToEdit}
        defaultStatus={defaultStatus}
        onClose={handleCloseModal}
        onSave={handleSaveTask}
      />
    </div>
  );
};

export default App;
